from pathlib import Path
import base64,html,re,json
O=Path(__file__).parent;R=Path('/home/user/repo');A=(R/'docs/current/CATALOG-LED-AUDIT.md').read_text()
def asset(p,m):return 'data:'+m+';base64,'+base64.b64encode(p.read_bytes()).decode()
def fmt(t):
 t=html.escape(t);t=re.sub(r'\*\*(.*?)\*\*',r'<b>\1</b>',t);t=re.sub(r'`([^`]+)`',r'<code>\1</code>',t)
 t=re.sub(r'\[([^\]]+)\]\((https?://[^)]+)\)',r'<a href="\2" target="_blank" rel="noopener noreferrer">\1</a>',t)
 return '<p>'+t.replace('\n\n','</p><p>').replace('\n','<br>')+'</p>'
findings=[]
for match in re.finditer(r'^### (CAT-A\d+.*?)\n(.*?)(?=^### |^## |\Z)',A,re.M|re.S):
 title,body=match[1],match[2].strip();findings.append('<details'+(' open' if title.startswith('CAT-A01 ') else '')+'><summary>'+html.escape(title)+'</summary><div>'+fmt(body)+'</div></details>')
assert len(findings)==15
